package com.medtrack.tracking.controller; import com.medtrack.tracking.dto.*; import com.medtrack.tracking.service.TrackingService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/shipments/{shipmentId}") public class TrackingController {private final TrackingService service;public TrackingController(TrackingService s){service=s;}@GetMapping("/tracking")@PreAuthorize("isAuthenticated()")public TrackingResponse history(@PathVariable UUID shipmentId){return service.history(shipmentId);}@PostMapping("/events")@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('LOGISTICS_COORDINATOR')")public ResponseEntity<TrackingResponse> event(@AuthenticationPrincipal String user,@PathVariable UUID shipmentId,@Valid @RequestBody TrackingEventRequest r){return ResponseEntity.status(201).body(service.record(UUID.fromString(user),shipmentId,r));}}
